/* Doe image-resize runtime fix. The original Prism blob is kept at prism.core.min.js. */
(function () {
    // prism.min.js is loaded before app.js; keep Prism synchronous so the existing
    // application boot order stays unchanged.
    if (typeof document !== 'undefined' && document.readyState === 'loading') {
        document.write('<script src="prism.core.min.js"><\/script>');
    } else if (typeof document !== 'undefined') {
        const prismScript = document.createElement('script');
        prismScript.src = 'prism.core.min.js';
        document.head.appendChild(prismScript);
    }

    const STYLE_ID = 'doe-image-resize-runtime-fix';
    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
        html body .task-detail-body .markdown-body .image-resize-handle {
            position: absolute !important;
            right: -7px !important;
            bottom: -7px !important;
            width: 16px !important;
            height: 16px !important;
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            padding: 0 !important;
            border: 0 !important;
            background: transparent !important;
            box-shadow: none !important;
            cursor: nwse-resize !important;
            z-index: 30 !important;
            opacity: 1 !important;
        }
        html body .task-detail-body .markdown-body .image-resize-handle::before {
            content: '↘' !important;
            display: block !important;
            color: var(--text-secondary) !important;
            font-size: 15px !important;
            line-height: 16px !important;
            font-weight: 700 !important;
            text-shadow: 0 1px 2px rgba(0,0,0,.25) !important;
            transform: translate(1px, 1px) !important;
        }
        html body .task-detail-body .markdown-body .image-resize-handle::after {
            content: none !important;
            display: none !important;
        }
        html body:has(.image-resizer-wrapper.is-resizing),
        html body:has(.image-resizer-wrapper.is-resizing) * {
            cursor: nwse-resize !important;
        }
    `;
    document.head.appendChild(style);

    const decodeHtml = (value) => {
        const ta = document.createElement('textarea');
        ta.innerHTML = value || '';
        return ta.value;
    };

    const readStoredSize = (wrapper) => {
        const md = decodeHtml(wrapper.dataset.md || '');
        const match = md.match(/\{\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*\}\s*$/);
        if (!match) return null;
        const width = Number(match[1]);
        const height = Number(match[2]);
        return width > 0 && height > 0 ? { width, height, md } : null;
    };

    const getVisibleViewportRight = (wrapper) => {
        const render = document.getElementById('task-desc-render');
        if (!render) return null;
        const wrapperRect = wrapper.getBoundingClientRect();
        const renderRect = render.getBoundingClientRect();
        return Math.max(50, renderRect.right - wrapperRect.left);
    };

    const syncVisibleSize = (wrapper) => {
        if (!wrapper || wrapper.classList.contains('is-resizing')) return;
        const stored = readStoredSize(wrapper);
        if (!stored) return;

        const maxWidth = getVisibleViewportRight(wrapper);
        const desiredVisibleWidth = Math.min(stored.width, maxWidth ?? stored.width);
        const visibleHeight = desiredVisibleWidth < stored.width
            ? Math.max(50, desiredVisibleWidth * stored.height / stored.width)
            : stored.height;

        if (Math.abs(wrapper.getBoundingClientRect().width - desiredVisibleWidth) > 0.5) {
            wrapper.style.width = `${desiredVisibleWidth}px`;
        }
        if (Math.abs(wrapper.getBoundingClientRect().height - visibleHeight) > 0.5) {
            wrapper.style.height = `${visibleHeight}px`;
        }
    };

    const observed = new WeakSet();
    const attachObserver = (wrapper) => {
        if (!wrapper || observed.has(wrapper) || typeof ResizeObserver === 'undefined') return;
        observed.add(wrapper);
        const ro = new ResizeObserver(() => syncVisibleSize(wrapper));
        ro.observe(wrapper);
        wrapper.__doeImageResizeObserver = ro;
        syncVisibleSize(wrapper);
    };

    const scanImages = (root) => {
        (root || document).querySelectorAll?.('.image-resizer-wrapper.has-custom-size').forEach(attachObserver);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => scanImages(document), { once: true });
    } else {
        scanImages(document);
    }

    const mutationObserver = new MutationObserver((mutations) => {
        for (const mutation of mutations) {
            mutation.addedNodes.forEach(node => {
                if (node.nodeType !== 1) return;
                if (node.matches?.('.image-resizer-wrapper.has-custom-size')) attachObserver(node);
                scanImages(node);
            });
        }
    });
    mutationObserver.observe(document.documentElement, { childList: true, subtree: true });

    document.addEventListener('mousedown', (e) => {
        if (e.button !== 0) return;
        const handle = e.target.closest?.('.image-resize-handle');
        if (!handle) return;

        const wrapper = handle.closest('.image-resizer-wrapper');
        const renderDiv = document.getElementById('task-desc-render');
        const descWrapper = document.querySelector('.description-wrapper');
        if (!wrapper || !renderDiv) return;

        // Replace the old image-resize handler entirely; otherwise both handlers
        // mutate the same wrapper and produce the ghost/offset resize artifact.
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        const stored = readStoredSize(wrapper);
        const wrapperRect = wrapper.getBoundingClientRect();
        const startX = e.clientX;
        const startY = e.clientY;
        const storedWidth = stored?.width || wrapperRect.width;
        const storedHeight = stored?.height || wrapperRect.height;
        const aspectRatio = storedWidth / Math.max(1, storedHeight);
        const hadExplicitDescriptionHeight = !!(descWrapper && descWrapper.style.height.trim());
        const baseDescriptionHeight = hadExplicitDescriptionHeight
            ? parseFloat(descWrapper.style.height) || descWrapper.getBoundingClientRect().height
            : null;

        let desiredWidth = storedWidth;
        let desiredHeight = storedHeight;

        const minSize = 50;
        wrapper.classList.add('is-resizing', 'has-custom-size');
        document.body.style.userSelect = 'none';

        const ensureDescriptionRoom = () => {
            if (!descWrapper) return;
            if (!hadExplicitDescriptionHeight) return;
            const descRect = descWrapper.getBoundingClientRect();
            const imageRect = wrapper.getBoundingClientRect();
            const requiredHeight = Math.max(
                baseDescriptionHeight || 0,
                imageRect.bottom - descRect.top + 18
            );
            if (requiredHeight > descRect.height + 0.5) {
                descWrapper.style.height = `${requiredHeight}px`;
            }
        };

        const onMove = (moveEvent) => {
            desiredWidth = Math.max(minSize, storedWidth + (moveEvent.clientX - startX));
            desiredHeight = Math.max(minSize, storedHeight + (moveEvent.clientY - startY));
            if (moveEvent.shiftKey) desiredHeight = Math.max(minSize, desiredWidth / aspectRatio);

            const availableWidth = getVisibleViewportRight(wrapper) ?? desiredWidth;
            const visibleWidth = Math.min(desiredWidth, availableWidth);
            const widthClamped = visibleWidth < desiredWidth - 0.5;
            const visibleHeight = widthClamped
                ? Math.max(minSize, visibleWidth * (desiredHeight / desiredWidth))
                : desiredHeight;

            wrapper.style.width = `${visibleWidth}px`;
            wrapper.style.height = `${visibleHeight}px`;
            ensureDescriptionRoom();
        };

        const onUp = async () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            document.body.style.userSelect = '';

            const finalWidth = Math.round(desiredWidth);
            const finalHeight = Math.round(desiredHeight);
            const originalMd = decodeHtml(wrapper.dataset.md || '');
            const match = originalMd.match(/!\[([^\]]*)\]\(([^)]+)\)(?:\{[^}]+\})?/);
            const newMd = match
                ? originalMd.replace(match[0], `![${match[1]}](${match[2]}){${finalWidth}, ${finalHeight}}`)
                : originalMd;

            try {
                if (typeof cmEditor !== 'undefined' && cmEditor && newMd !== originalMd) {
                    const idx = cmEditor.getValue().indexOf(originalMd);
                    if (idx !== -1) {
                        const from = cmEditor.posFromIndex(idx);
                        const to = cmEditor.posFromIndex(idx + originalMd.length);
                        cmEditor.replaceRange(newMd, from, to);
                    }
                    wrapper.dataset.md = typeof escapeHtml === 'function' ? escapeHtml(newMd) : newMd;
                    if (typeof lastSavedValue !== 'undefined') lastSavedValue = cmEditor.getValue();

                    const taskModal = document.getElementById('task-modal');
                    const taskId = taskModal?.dataset.taskId;
                    if (taskId) {
                        if (typeof updateTask === 'function') {
                            await updateTask(taskId, { description: cmEditor.getValue() });
                        } else if (typeof API_BASE !== 'undefined') {
                            await fetch(`${API_BASE}/tasks/${taskId}`, {
                                method: 'PUT',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ description: cmEditor.getValue() })
                            });
                        }
                    }
                    if (typeof bumpModalUpdatedDate === 'function') bumpModalUpdatedDate();
                }
            } catch (err) {
                console.error('[Image resize] save failed', err);
            }

            if (hadExplicitDescriptionHeight && descWrapper) {
                const descRect = descWrapper.getBoundingClientRect();
                const imageRect = wrapper.getBoundingClientRect();
                const requiredHeight = imageRect.bottom - descRect.top + 18;
                descWrapper.style.height = `${Math.max(baseDescriptionHeight || 0, requiredHeight)}px`;
                // If the image now fits again, restore the user's exact divider height.
                if (requiredHeight <= (baseDescriptionHeight || 0) + 0.5) {
                    descWrapper.style.height = `${baseDescriptionHeight}px`;
                }
            } else if (descWrapper) {
                // No explicit user height existed before the image resize. Do not
                // leave a synthetic inline height behind after the drag.
                descWrapper.style.height = '';
            }

            wrapper.classList.remove('is-resizing');
            wrapper.dataset.justResized = '1';
            setTimeout(() => { delete wrapper.dataset.justResized; }, 300);
            syncVisibleSize(wrapper);
        };

        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp, { once: true });
        onMove(e);
    }, true);
})();
